package com.lore.zzal.game;
import com.lore.zzal.pet.*;import com.lore.zzal.pet.receipt.*;import com.lore.zzal.game.dto.*;import com.lore.common.exception.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.orm.jpa.*;import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter;import org.springframework.data.jpa.repository.support.JpaRepositoryFactory;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.interceptor.TransactionInterceptor;import org.springframework.transaction.annotation.AnnotationTransactionAttributeSource;import org.springframework.aop.framework.ProxyFactory;import org.springframework.test.util.ReflectionTestUtils;import java.time.Instant;import java.util.*;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="LORE_GAME_RECEIPT_DB_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:55420/lore_game_receipt_[0-9_]+_test")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class GameGuessReceiptPostgresTest {
 final Instant now=Instant.parse("2026-10-18T03:00:00Z");jakarta.persistence.EntityManagerFactory emf;jakarta.persistence.EntityManager em;JpaTransactionManager tm;TransactionTemplate tx;JdbcTemplate jdbc;ZzalPetRepository owners;ZzalGameRepository games;ActionReceiptRepository receipts;Long petId,gameId;boolean failSave;com.lore.zzal.piece.PieceService pieces;
 @BeforeAll void schema(){var ds=new DriverManagerDataSource(System.getenv("LORE_GAME_RECEIPT_DB_URL"),System.getenv("LORE_TEST_DB_USERNAME"),System.getenv("LORE_TEST_DB_PASSWORD"));jdbc=new JdbcTemplate(ds);org.flywaydb.core.Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var f=new LocalContainerEntityManagerFactoryBean();f.setDataSource(ds);f.setPackagesToScan("com.lore.zzal.pet","com.lore.zzal.game");f.setJpaVendorAdapter(new HibernateJpaVendorAdapter());f.setJpaPropertyMap(Map.of("hibernate.hbm2ddl.auto","validate","hibernate.physical_naming_strategy","org.hibernate.boot.model.naming.PhysicalNamingStrategySnakeCaseImpl"));f.afterPropertiesSet();emf=f.getObject();em=SharedEntityManagerCreator.createSharedEntityManager(emf);tm=new JpaTransactionManager(emf);tx=new TransactionTemplate(tm);var factory=new JpaRepositoryFactory(em);owners=factory.getRepository(ZzalPetRepository.class);games=factory.getRepository(ZzalGameRepository.class);receipts=factory.getRepository(ActionReceiptRepository.class);}
 @AfterAll void close(){if(emf!=null)emf.close();}
 @BeforeEach void seed(){failSave=false;pieces=mock(com.lore.zzal.piece.PieceService.class);petId=tx.execute(s->{var p=ZzalPet.draft(900701L,"images/synthetic/game",now.minusSeconds(100));ReflectionTestUtils.setField(p,"createdAt",now);ReflectionTestUtils.setField(p,"updatedAt",now);ReflectionTestUtils.setField(p,"phase",PetPhase.ALIVE);ReflectionTestUtils.setField(p,"hatchedAt",now);ReflectionTestUtils.setField(p,"tutorialStep",99);em.persist(p);em.flush();return p.getId();});gameId=tx.execute(s->{var g=ZzalGame.start(900701L,petId,GameKind.LEFT_RIGHT,"LLLLL",now);em.persist(g);em.flush();return g.getId();});}
 @SuppressWarnings("unchecked") <T>T proxy(T target){var p=new ProxyFactory(target);p.setProxyTargetClass(true);p.addAdvice(new TransactionInterceptor(tm,new AnnotationTransactionAttributeSource()));return(T)p.getProxy();}
 GameGuessRequestService service(){PetService target=mock(PetService.class,CALLS_REAL_METHODS);doAnswer(i->{var p=owners.findByIdForUpdate(petId).orElseThrow();if(p.isTraveling())throw new BusinessException(ErrorCode.ZZAL_TRAVELING);return p;}).when(target).alive(anyLong(),anyLong(),any());doAnswer(i->{var p=owners.findByIdForUpdate(petId).orElseThrow();ReflectionTestUtils.setField(p,"settledAt",now);return p;}).when(target).refresh(anyLong(),anyLong(),any());doAnswer(i->{((Runnable)i.getArgument(1)).run();return new PetService.Action(i.getArgument(0),List.of());}).when(target).withUnlockDiff(any(),any());var pets=proxy(target);var gameService=proxy(new GameService(games,pets,mock(RewardService.class),pieces,mock(com.lore.zzal.night.BakeTrigger.class),3,false));var repo=mock(ActionReceiptRepository.class);when(repo.findByPetIdAndRequestId(any(),any())).thenAnswer(i->receipts.findByPetIdAndRequestId(i.getArgument(0),i.getArgument(1)));when(repo.saveAndFlush(any())).thenAnswer(i->{var out=receipts.saveAndFlush(i.getArgument(0));if(failSave)throw new IllegalStateException("after durable flush within rollback TX");return out;});var delivery=proxy(new GameGuessDeliveryService(owners,pets,gameService,games,repo,tools.jackson.databind.json.JsonMapper.builder().build()));return new GameGuessRequestService(gameService,pets,proxy(new ProtectedGameGuessBoundary(pets,delivery)));}
 GameRequests.Guess request(UUID id,int round){return new GameRequests.Guess(GameRequests.Side.LEFT,id,round);}
 int round(){return jdbc.queryForObject("select length(picks) from zzal_game where id=?",Integer.class,gameId);}int receipts(){return jdbc.queryForObject("select count(*) from zzal_action_receipt where pet_id=?",Integer.class,petId);}
 @Test void duplicateReplaysOneDurableRound(){var s=service();var id=UUID.randomUUID();var first=s.guess(900701L,petId,gameId,request(id,0),now);assertThat(s.guess(900701L,petId,gameId,request(id,0),now)).isEqualTo(first);assertThat(round()).isEqualTo(1);assertThat(receipts()).isEqualTo(1);}
 @Test void staleRoundAndCareIdentityCannotAdvanceGame(){var s=service();var id=UUID.randomUUID();s.guess(900701L,petId,gameId,request(id,0),now);assertThatThrownBy(()->s.guess(900701L,petId,gameId,request(UUID.randomUUID(),0),now)).isInstanceOf(BusinessException.class);var care=UUID.randomUUID();tx.executeWithoutResult(st->receipts.saveAndFlush(new ActionReceipt(petId,care,"CARE_PET","0".repeat(64),"{}",now)));assertThatThrownBy(()->s.guess(900701L,petId,gameId,request(care,1),now)).isInstanceOf(BusinessException.class);assertThat(round()).isEqualTo(1);}
 @Test void receiptFailureRollsBackGuessButPreservesPriorSettlement(){failSave=true;assertThatThrownBy(()->service().guess(900701L,petId,gameId,request(UUID.randomUUID(),0),now)).isInstanceOf(IllegalStateException.class);assertThat(round()).isZero();assertThat(receipts()).isZero();assertThat((Object)tx.execute(st->owners.findById(petId).orElseThrow().getSettledAt())).isEqualTo(now);}
 @Test void ambientTransactionFailsBeforeSettlement(){var s=service();assertThatThrownBy(()->tx.execute(st->{owners.findByIdForUpdate(petId).orElseThrow();return s.guess(900701L,petId,gameId,request(UUID.randomUUID(),0),now);})).isInstanceOf(org.springframework.transaction.IllegalTransactionStateException.class);assertThat(round()).isZero();assertThat(receipts()).isZero();assertThat((Object)tx.execute(st->owners.findById(petId).orElseThrow().getSettledAt())).isNotEqualTo(now);}
 @Test void simultaneousFirstDeliveryConsumesOnlyOneRound()throws Exception{var s=service();var id=UUID.randomUUID();var start=new java.util.concurrent.CountDownLatch(1);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{java.util.concurrent.Callable<GameResponses.Guess> c=()->{start.await();return s.guess(900701L,petId,gameId,request(id,0),now);};var a=pool.submit(c);var b=pool.submit(c);start.countDown();assertThat(a.get(8,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(b.get(8,java.util.concurrent.TimeUnit.SECONDS));assertThat(round()).isEqualTo(1);assertThat(receipts()).isEqualTo(1);}finally{start.countDown();pool.shutdownNow();}}
 @Test void finishedRoundReceiptCannotRepeatRewards(){var s=service();s.guess(900701L,petId,gameId,request(UUID.randomUUID(),0),now);s.guess(900701L,petId,gameId,request(UUID.randomUUID(),1),now);var id=UUID.randomUUID();var first=s.guess(900701L,petId,gameId,request(id,2),now);assertThat(first.finished()).isTrue();assertThat(s.guess(900701L,petId,gameId,request(id,2),now)).isEqualTo(first);assertThat(round()).isEqualTo(3);verify(pieces,times(1)).count(any(),eq(com.lore.zzal.piece.PieceEvent.GAME));}
}
